package local.skyfamily;
import android.content.res.Configuration;import android.os.Bundle;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
public class ExploreActivity extends UnifiedActivity {
 boolean cleaningHome=false,exploreRoute=false,effectsRunning=false;SeasonalOverlay seasonal;
 static final String[] EFFECTS={"off","auto","leaves","rain","snow","snowmen","petals","sparkles","confetti"};
 static final String[] EFFECT_NAMES={"Off","Match seasonal theme","Falling leaves","Rain","Falling snow","Snowmen and falling snow","Falling petals","Drifting sparkles","Falling confetti"};
 @Override public void onCreate(Bundle state){super.onCreate(state);android.content.SharedPreferences.Editor edit=prefs.edit();if(!prefs.contains("visual.scene"))edit.putString("visual.scene","auto");if(!prefs.contains("visual.motion"))edit.putBoolean("visual.motion",true);edit.apply();refreshEffects();}
 @Override ThemeArt.Palette palette(){String theme=prefs==null?"winter":ThemeArt.active(prefs);int background=PAPER,rail=PAPER2,surface=CARD,color=INK;if(theme.equals("winter")){background=0xffedf4f8;rail=0xffdce9f1;surface=0xfff8fcff;color=0xff27567c;}else if(theme.equals("christmas")){background=0xffedf3eb;rail=0xffdae6d6;surface=0xfff8fbf5;color=0xffa6312d;}else if(theme.equals("fall")){background=0xfff5ead9;rail=0xffe8d5b9;surface=0xfffffaf1;color=0xff985321;}else if(theme.equals("halloween")){background=0xfff0e9f2;rail=0xffe0d4e7;surface=0xfffcf7fc;color=0xff995022;}else if(theme.equals("spring")||theme.equals("stpatrick")){background=0xffedf3e8;rail=0xffdde8d4;surface=0xfffafdf5;color=0xff276340;}else if(theme.equals("summer")){background=0xfffaf2db;rail=0xffeee0b8;surface=0xfffffcf2;color=0xff725212;}else if(theme.equals("birthday")){background=0xfff7eaf0;rail=0xffecd4e1;surface=0xfffff8fb;color=0xff85416c;}ThemeArt.Palette p=new ThemeArt.Palette(theme,background,rail,surface,color);p.muted=MUTE;return p;}
 @Override int surfaceColor(int color){int mapped=super.surfaceColor(color);ThemeArt.Palette p=palette();return mapped==PAPER?p.bg:mapped==PAPER2?p.rail:mapped==CARD?p.surface:mapped;}
 @Override void button(String title,Runnable action){if(cleaningHome&&title.startsWith("Watch & Explore"))return;if(title.equals("Weather TV / external webpage"))return;super.button(title,action);if(body.getChildCount()>0)categoryIcons(body.getChildAt(body.getChildCount()-1));}
 @Override void home(){cleaningHome=true;try{super.home();removeHomeScenes(body);}finally{cleaningHome=false;}}
 void removeHomeScenes(View root){if(!(root instanceof ViewGroup))return;ViewGroup group=(ViewGroup)root;for(int i=group.getChildCount()-1;i>=0;i--){View child=group.getChildAt(i);if(child instanceof ThemeArt.Scene)group.removeViewAt(i);else removeHomeScenes(child);}}
 @Override void shortcut(LinearLayout row,String title,Runnable action){if(title.equals("Weather TV"))return;if(title.equals("Explore")){super.shortcut(row,"Calendar",()->calendar());super.shortcut(row,"Notes",()->notes());}super.shortcut(row,title,action);categoryIcons(row);}
 @Override void page(String title){super.page(title);if(sidebar!=null){frameRail("Explore",group(title).equals("Explore"),()->frameExplore());View entry=sidebar.getChildAt(sidebar.getChildCount()-1);sidebar.removeView(entry);sidebar.addView(entry,Math.min(5,sidebar.getChildCount()));}}
 @Override String group(String title){String s=title.toLowerCase(Locale.US);if(exploreRoute||s.equals("explore")||s.contains("watch")||s.contains("planetarium")||s.contains("space")||s.contains("cameras")||s.contains("weather tv")||s.contains("news")||s.startsWith("santa"))return "Explore";return super.group(title);}
 @Override void frameRail(String title,boolean selected,Runnable action){super.frameRail(title,selected,action);categoryIcons(sidebar.getChildAt(sidebar.getChildCount()-1));}
 @Override void frameCard(LinearLayout row,String title,String detail,Runnable action){super.frameCard(row,title,detail,action);categoryIcons(row.getChildAt(row.getChildCount()-1));}
 @Override TextView iconControl(LinearLayout row,String title,Runnable action){TextView text=super.iconControl(row,title,action);categoryIcons(row);return text;}
 void categoryIcons(View root){if(!(root instanceof ViewGroup))return;ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){View child=group.getChildAt(i);if(child instanceof ControlIcon){ControlIcon old=(ControlIcon)child;int kind=DestinationIcon.kind(old.label);if(kind!=0){ViewGroup.LayoutParams size=old.getLayoutParams();group.removeViewAt(i);group.addView(new DestinationIcon(this,kind,palette().accent),i,size);}}else categoryIcons(child);}}
 @Override void frameExplore(){page("Explore");tile("Wildlife & aquariums","Nature, zoo cameras and the Watch library","",accent,()->watchExplore());tile("Search videos","Find videos here and play them in NotPipe","",accent,()->youtubeSearch());tile("Planetarium & sky","Recorded shows, sky cameras and NASA","",accent,()->space());tile("World cameras","Beaches, harbours and places","",accent,()->worldCameras());tile("Weather TV","Retro weather and provider music controls","",accent,()->weatherTvIntro());tile("News","Built-in and custom RSS","",accent,()->news());tile("Santa","Seasonal countdown and fictional preview","",accent,()->santa());endgrid();}
 @Override void watchExplore(){exploreRoute=true;try{super.watchExplore();}finally{exploreRoute=false;}}
 @Override void openPublic(String title,String url){exploreRoute=true;try{String query=android.net.Uri.encode(title+" videos");android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse("https://www.youtube.com/results?search_query="+query));try{startActivity(intent);}catch(android.content.ActivityNotFoundException e){toast("No app can open this YouTube link");}}finally{exploreRoute=false;}}
 void youtubeSearch(){page("Search videos");text("Search YouTube videos here. Results come from a public Invidious search API; availability depends on its volunteer-run instances.");EditText query=input("Search videos","");button("Search",()->{String q=query.getText().toString().trim();if(q.isEmpty()){toast("Enter a search");return;}searchYouTube(q);});}
 void searchYouTube(String query){page("Video results");text("Searching for: "+query);final TextView status=paperText("Connecting to search service...",14,MUTE);body.addView(status);int stamp=revision;work(()->{JSONArray results=null;Exception last=null;String[] hosts={"https://yt.chocolatemoo53.com","https://invidious.tiekoetter.com","https://invidious.nerdvpn.de","https://inv.nadeko.net"};for(String host:hosts){try{String url=host+"/api/v1/search?q="+android.net.Uri.encode(query)+"&type=video&page=1&region=US";JSONArray found=new JSONArray(new String(request(url,"GET",null,"",4000000),"UTF-8"));results=found;break;}catch(Exception e){last=e;}}if(results==null){final String reason="Search unavailable. Public search servers may be offline."+(last==null?"":" "+last.getMessage());ui.post(()->{if(stamp==revision)status.setText(reason);});return;}final JSONArray rows=results;ui.post(()->{if(stamp!=revision)return;status.setText(rows.length()==0?"No video results found. Try another search.":rows.length()+" search results / Tap a video to play in NotPipe.");for(int i=0;i<rows.length();i++){JSONObject item=rows.optJSONObject(i);if(item==null||!item.optString("type","video").equals("video"))continue;String id=item.optString("videoId");if(id.isEmpty())continue;LinearLayout card=new LinearLayout(this);card.setOrientation(0);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(10),dp(10),dp(10),dp(10));card.setBackground(shape(surface,edge,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(10);body.addView(card,cp);ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(thumb,new LinearLayout.LayoutParams(dp(132),dp(82)));JSONArray thumbnails=item.optJSONArray("videoThumbnails");String image="";if(thumbnails!=null&&thumbnails.length()>0){JSONObject t=thumbnails.optJSONObject(thumbnails.length()-1);if(t!=null)image=t.optString("url");}if(image.startsWith("https://"))picture(thumb,image,"");LinearLayout details=new LinearLayout(this);details.setOrientation(1);details.setPadding(dp(10),0,0,0);card.addView(details,new LinearLayout.LayoutParams(0,-2,1));TextView title=new TextView(this);title.setText(item.optString("title","Untitled video"));title.setTextColor(fg);title.setTextSize(16);title.setMaxLines(3);details.addView(title);TextView meta=new TextView(this);meta.setText(item.optString("author","Unknown channel")+"  /  "+item.optString("lengthSeconds","")+" sec  /  "+item.optString("viewCount","")+" views");meta.setTextColor(muted);meta.setTextSize(12);details.addView(meta);card.setOnClickListener(v->playInNotPipe(id));}});});}
 void playInNotPipe(String videoId){try{android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse("https://www.youtube.com/watch?v="+android.net.Uri.encode(videoId)));intent.setPackage("io.github.gohoski.notpipe");startActivity(intent);}catch(android.content.ActivityNotFoundException e){toast("NotPipe is not installed or cannot open YouTube videos.");}catch(Exception e){toast("Could not open video in NotPipe.");}}
 @Override void space(){page("Planetarium & sky");section("Recorded planetarium shows");destination("ESO planetarium / fulldome","Recorded shows and videos, not live sky tracking.","https://www.eso.org/public/videos/archive/category/fulldome/");section("Sky and space viewing");destination("Northern Lights / Explore","Provider sky camera; weather and darkness affect visibility.","https://explore.org/livecams/aurora-borealis-northern-lights/northern-lights-cam");destination("NASA live programming","Official programming; availability varies.","https://www.nasa.gov/live/");destination("ISS / Earth camera","Official destination; not a guaranteed working stream.","https://eol.jsc.nasa.gov/ESRS/HDEV/");}
 void worldCameras(){page("World cameras");destination("Beaches","Provider viewing pages.","https://www.skylinewebcams.com/en/live-cams-category/beach-cams.html");destination("Harbours and marinas","Provider viewing pages.","https://www.skylinewebcams.com/en/live-cams-category/seaport-cams.html");destination("World cameras / historic places","Provider directory; availability varies.","https://www.skylinewebcams.com/en/webcam.html");}
 @Override void games(int selected){super.games(selected);if(selected!=2)button("Pocket creature",()->pet());}
 @Override void visualSettings(){page("Themes and celebrations");text("Seasonal colours and transparent decorations apply across this app, not just Home. Decorations do not receive touches or become part of saved drawings.");section("Seasonal palette");Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,ThemeArt.LABELS));mode.setSelection(Math.max(0,Arrays.asList(ThemeArt.MODES).indexOf(getMode())));body.addView(mode);section("Screen-wide decoration");Spinner scene=new Spinner(this);scene.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,EFFECT_NAMES));scene.setSelection(Math.max(0,Arrays.asList(EFFECTS).indexOf(prefs.getString("visual.scene","auto"))));body.addView(scene);CheckBox motion=new CheckBox(this);motion.setText("Animate falling / drifting decorations");motion.setChecked(prefs.getBoolean("visual.motion",true));body.addView(motion);section("Hemisphere");String[] hemispheres={"auto","north","south"};Spinner hemisphere=new Spinner(this);hemisphere.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Weather location / otherwise Northern Hemisphere","Northern Hemisphere","Southern Hemisphere"}));hemisphere.setSelection(Math.max(0,Arrays.asList(hemispheres).indexOf(prefs.getString("visual.hemisphere","auto"))));body.addView(hemisphere);button("Save theme choices",()->{prefs.edit().putString("visual.mode",ThemeArt.MODES[mode.getSelectedItemPosition()]).putString("visual.scene",EFFECTS[scene.getSelectedItemPosition()]).putBoolean("visual.motion",motion.isChecked()).putString("visual.hemisphere",hemispheres[hemisphere.getSelectedItemPosition()]).apply();home();});button("Manage local birthdays",()->birthdays());text("Choose Off to remove decoration, or turn motion off for a still decoration. Existing saved Off/motion choices are retained. Animation pauses while the app is backgrounded. Effects stay inside this app, not Android settings or an external browser.");}
 String seasonalKind(){String selected=prefs.getString("visual.scene","auto");if(!selected.equals("auto"))return selected;String theme=ThemeArt.active(prefs);return theme.equals("fall")||theme.equals("halloween")?"leaves":theme.equals("winter")||theme.equals("christmas")?"snowmen":theme.equals("spring")?"petals":theme.equals("birthday")?"confetti":"sparkles";}
 void refreshEffects(){if(seasonal!=null&&prefs!=null){seasonal.configure(seasonalKind(),prefs.getBoolean("visual.motion",true));seasonal.running(effectsRunning);}}
 @Override public void onContentChanged(){super.onContentChanged();if(prefs==null)return;if(seasonal!=null)seasonal.running(false);View root=findViewById(android.R.id.content);if(root instanceof FrameLayout){FrameLayout content=(FrameLayout)root;seasonal=new SeasonalOverlay(this);content.addView(seasonal,new FrameLayout.LayoutParams(-1,-1));refreshEffects();}}
 @Override protected void onResume(){super.onResume();effectsRunning=true;refreshEffects();}
 @Override protected void onPause(){effectsRunning=false;if(seasonal!=null)seasonal.running(false);super.onPause();}
 @Override protected void onDestroy(){effectsRunning=false;if(seasonal!=null)seasonal.running(false);super.onDestroy();}
}
